; Title module: title screen, name entry, ROM text/inventory patches and
; Goku's arrival at the Mana Sword.
;   code  !CODE_MISC ($AB:8000-FFFF, ROM 0x2B8000)
;   data  !DATA_MISC ($EB:0000-7FFF, ROM 0x2B0000), mostly generated by
;         snes/gen/title.mjs into dist/snes/gen/title/title.asm
;   WRAM  !RAM_MISC  ($7E:DD80, $80 bytes)
;   SRAM  !PERSIST_MISC ($31:6B00, $100 bytes) and !persist_goku_active
; See docs/agents/snes-port/title.md.

; ---------------------------------------------------------------------------
; WRAM (!RAM_MISC, $80 bytes; cleared by core_boot on reset)
!title_flags        = !RAM_MISC+$00   ; byte: bit0 name prefilled since the last title entry
!title_tmp          = !RAM_MISC+$02   ; word scratch (main thread only)
!title_tmp2         = !RAM_MISC+$04   ; word scratch (main thread only)
!title_phase        = !RAM_MISC+$06   ; byte: arrival phase (!TITLE_PH_*)
!title_ticks        = !RAM_MISC+$08   ; word: field frames in the current arrival phase
!title_hero_mode    = !RAM_MISC+$0A   ; byte: 0 native hero, 1 hidden, 2 hop sprite (see doc)
!title_hero_x       = !RAM_MISC+$0C   ; word: hop sprite screen x (32x32 top-left)
!title_hero_y       = !RAM_MISC+$0E   ; word: hop sprite screen y
!title_hero_frame   = !RAM_MISC+$10   ; byte: Goku sheet column for the hop (37 air, 36 landed)
!title_pod_frame    = !RAM_MISC+$11   ; byte: pod art in VRAM ($FF none)
!title_obj_state    = !RAM_MISC+$12   ; byte: bit0 scenery tiles uploaded on this map visit
!title_scr_x        = !RAM_MISC+$14   ; word: sword/crater anchor screen x this frame
!title_scr_y        = !RAM_MISC+$16   ; word: anchor screen y
!title_oam_next     = !RAM_MISC+$18   ; word: next free OAM buffer offset while drawing
!title_flash        = !RAM_MISC+$1A   ; 3 bytes: flash channel deltas (r,g,b)
!title_status       = !RAM_MISC+$1E   ; byte: bit1 title program patched (diagnostic)

!TITLE_PH_PROLOGUE = 0
!TITLE_PH_QUEUED   = 1
!TITLE_PH_DESCENT  = 2
!TITLE_PH_IMPACT   = 3
!TITLE_PH_GHOST    = 4
!TITLE_PH_DIALOGUE = 5
!TITLE_PH_COMPLETE = 6

; Persistent (SRAM !PERSIST_MISC): survives saves through the core sidecars.
!persist_title_arrival = !PERSIST_MISC+$00 ; byte: bit0 Goku arrived, bit1 crater/pod scenery on map 128

pushpc
org !DATA_MISC
title_data_start:
incsrc "title/title.asm"
incsrc "data.asm"
title_data_end:
assert title_data_end <= !DATA_MISC+$8000, "title data bank overflow"

org !CODE_MISC
title_code_start:
incsrc "boot.asm"
incsrc "names.asm"
incsrc "patches.asm"
incsrc "arrival.asm"
title_code_end:
assert title_code_end <= !CODE_MISC+$8000, "title code bank overflow"
pullpc

incsrc "hooks.asm"
